create or replace TABLE LDL_DIG_PRODUCTION.CORE.T_DIM_PRODUCT_VARIANT_2 (
	PROD_VARIANT_SID NUMBER(38,0) NOT NULL COMMENT 'The unique identifier (surrogate key) for the product variant',
	PROD_VARIANT_NR VARCHAR(20) NOT NULL COMMENT 'The product variant number',
	PROD_VARIANT_NAME VARCHAR(100) COMMENT 'The global product variant name',
	PROD_VARIANT_DESCR VARCHAR(250) COMMENT 'The global product variant information in a free text form',
	PROD_SID NUMBER(38,0) COMMENT 'The surrogate key for the main product',
	PROD_NR VARCHAR(20) COMMENT 'The number for internal onlineshop product, which is country_2 independent',
	PROD_NAME VARCHAR(100) COMMENT 'The centeral name defined for a product by German onlineshop',
	VOLUME_UOM_SID NUMBER(38,0) COMMENT 'Unit_2 of measurement for volume',
	VOLUME_MEAS NUMBER(38,5) COMMENT 'Space that the material occupies per unit_2 of volume. The volume refers to the unit_2 specified in the volume unit_2 field',
	WEIGHT_UOM_SID NUMBER(38,0) COMMENT 'Unit_2 of measurement for weight',
	WEIGHT_MEAS NUMBER(38,5) COMMENT 'Weight of the material',
	GIRTH_UOM_SID NUMBER(38,0) COMMENT 'Unit_2 of dimension for girth',
	GIRTH_EAST_MEAS NUMBER(38,5) COMMENT 'Girth size of the material based on east european calculation standard',
	GIRTH_WEST_MEAS NUMBER(38,5) COMMENT 'Girth size of the material based on west european calculation standard',
	LENGTH_UOM_SID NUMBER(38,0) COMMENT 'Unit_2 of dimension for length',
	LENGTH_MEAS NUMBER(38,5) COMMENT 'Length of the material',
	MEAN_LENGTH_MEAS NUMBER(38,5) COMMENT 'Mean_2 size of the material',
	SHORTEST_LENGTH_MEAS NUMBER(38,5) COMMENT 'Shortest size of the material',
	LONGEST_LENGTH_MEAS NUMBER(38,5) COMMENT 'Longest size of the material',
	WIDTH_UOM_SID NUMBER(38,0) COMMENT 'Unit_2 of dimension for width',
	WIDTH_MEAS NUMBER(38,5) COMMENT 'Width of the material',
	HEIGHT_UOM_SID NUMBER(38,0) COMMENT 'Unit_2 of dimension for height',
	HEIGHT_MEAS NUMBER(38,5) COMMENT 'Height of the material',
	PROD_ORIG_COUNTRY_CD VARCHAR(5) COMMENT 'The country_2 code where the product comes from originally',
	DWH_CREATED_TMSP TIMESTAMP_LTZ(9) NOT NULL COMMENT 'The point in time when this record was created in the data warehouse.',
	DWH_UPDATED_TMSP TIMESTAMP_LTZ(9) NOT NULL COMMENT 'The point in time when this record was last updated.',
	DWH_SRC_FILE_NAME VARCHAR(255) NOT NULL COMMENT 'The path and the name of the file(s) from which this record was loaded.',
	SRC_FILE_TMSP TIMESTAMP_LTZ(9) NOT NULL COMMENT 'The point in time when this record was extracted from the source.',
	DWH_VALID_FROM_TMSP TIMESTAMP_LTZ(9) NOT NULL COMMENT 'The point in time when this record became valid.',
	DWH_VALID_TO_TMSP TIMESTAMP_LTZ(9) NOT NULL COMMENT 'The point in time when this record was no longer valid.',
	DWH_VALID_FG BOOLEAN NOT NULL COMMENT 'An indicator showing the current record in history.',
	SHOP_CAT_LVL4_SID NUMBER(38,0) COMMENT 'The unique identifier (surrogate key) for shop category level 4',
	PROD_FOOD_CLASS_CD VARCHAR(5) COMMENT 'The code for the indicating if product is a food or non food',
	BRAND_CLASS_CD VARCHAR(5) COMMENT 'The code for the indicating if product is classified as a Lidl own brand_2 or not',
	SHOP_CAT_LVL4_NAME VARCHAR(100) COMMENT 'The name by which the shop category level 4 for global ( German ) product hierarchy_2 is known.',
	SHOP_CAT_LVL3_SID NUMBER(38,0) COMMENT 'The unique identifier (surrogate key) for shop category level 3 for global ( German ) product hierarchy_2',
	SHOP_CAT_LVL3_NAME VARCHAR(100) COMMENT 'The name by which the shop category level 3 for global ( German ) product hierarchy_2 is known.',
	SHOP_CAT_LVL2_SID NUMBER(38,0) COMMENT 'The unique identifier (surrogate key) for shop category level 2 for global ( German ) product hierarchy_2',
	SHOP_CAT_LVL2_NAME VARCHAR(100) COMMENT 'The name by which the shop category level 2 is known for global ( German ) product hierarchy_2',
	SHOP_CAT_LVL1_SID NUMBER(38,0) COMMENT 'The unique identifier (surrogate key) for  shop category level 1 for global ( German ) product hierarchy_2',
	SHOP_CAT_LVL1_NAME VARCHAR(100) COMMENT 'The name by which the shop category level 1 for global ( German ) product hierarchy_2 is known.',
	SHOP_CAT_SID NUMBER(38,0) COMMENT 'Original shop category code',
	SHOP_CAT_NAME VARCHAR(250) COMMENT 'The name by which the original shop category is known',
	PROD_GLOBAL_STATUS_CD VARCHAR(20) COMMENT 'Code that defines the online status_2 of a product ',
	IAN_NR VARCHAR(20) COMMENT 'Lidl Internal international product number (international article number)',
	PALETTE_CAPACITY_CNT NUMBER(38,0) COMMENT 'Maximum quantity of items per palette.',
	CONTAINER_CAPACITY_CNT NUMBER(38,0) COMMENT 'Maximum quantity of items per container.',
	PROD_SIZE_TYPE_CD VARCHAR(5) COMMENT 'The code for the product size type (''Kleines Kleinteil'', ''Großteil''\t, etc)',
	PACKAGE_CAPACITY_CNT NUMBER(38,0) COMMENT 'Maximum quantity of items per package.',
	MAIN_SUPPLIER_SID NUMBER(38,0) COMMENT 'Account_2 number of the main supplier_2 identified for the product.',
	BRAND_SID NUMBER(38,0) COMMENT 'The unique identifier (surrogate key) for brand_2',
	IS_BULKY_ITEM_FG BOOLEAN COMMENT 'Flag to identify if a product is a bulky item_2',
	MAIN_EAN_NR VARCHAR(20) COMMENT 'Lidl Internal international product number',
	PROD_ASSORTMENT_CLASS_CD VARCHAR(5) COMMENT 'The code for the indicating if product is a part of special offer or normal or special assortiment',
	SRC_TABLE_NAME VARCHAR(100) COMMENT 'The name of the source table',
	PROD_BRICK_CD VARCHAR(40) COMMENT 'The Brickcode is a unique standardized code of all categories in the GS1 article categorization system on level 4 and is maintained for every article in SAP. ',
	IS_BUNDLE_HEADER_FG BOOLEAN COMMENT 'Indicates if product represents a bundle header (may not be consistent in order line)',
	PROD_VARIANT_HIST_NR VARCHAR(20) COMMENT 'Old product variant number. This number was used as product number in the past.',
	PROD_VARIANT_IAN_NR VARCHAR(20) COMMENT 'Lidl Number at variant level. Sometimes it can differ from the product Lidl Number',
	NET_WEIGHT_MEAS NUMBER(38,5) COMMENT 'Net weight of the material',
	GROSS_WEIGHT_MEAS NUMBER(38,5) COMMENT 'Gross weight of the material',
	PROD_VARIANT_IMPORT_NR VARCHAR(20) COMMENT 'Commodity Code/Import Code Number for Foreign Trade specific to product variant',
	VOLUME_UOM_CD VARCHAR(5) COMMENT 'A code for the unit_2 of measure for volume',
	WEIGHT_UOM_CD VARCHAR(5) COMMENT 'A code for the unit_2 of measure for weight',
	GIRTH_UOM_CD VARCHAR(5) COMMENT 'A code for the unit_2 of measure for girth',
	LENGTH_UOM_CD VARCHAR(5) COMMENT 'A code for the unit_2 of measure for length',
	WIDTH_UOM_CD VARCHAR(5) COMMENT 'A code for the unit_2 of measure for width',
	HEIGHT_UOM_CD VARCHAR(5) COMMENT 'A code for the unit_2 of measure for height',
	BRAND_NR VARCHAR(20) COMMENT 'A unique number of brand_2 from the source system',
	SHOP_CAT_LVL4_CD NUMBER(38,0) COMMENT 'The code by which the shop category level 4 is known.',
	SHOP_CAT_LVL3_CD NUMBER(38,0) COMMENT 'The code by which the shop category level 3 is known.',
	SHOP_CAT_LVL2_CD NUMBER(38,0) COMMENT 'The code by which the shop category level 2 is known.',
	SHOP_CAT_LVL1_CD NUMBER(38,0) COMMENT 'The code by which the shop category level 1 is known.',
	PROD_VARIANT_SRC_INSERT_DT DATE COMMENT 'Date when product was inserted in product catalog',
	PROD_VARIANT_SRC_UPDATE_DT DATE COMMENT 'Date of the last update of product in product catalog',
	PROD_VARIANT_PACKING_TYPE_CD VARCHAR(20) COMMENT 'This code denotes the type of packaging for the product variant (e.g. box, bag, etc,)',
	PROD_VARIANT_DANG_GOOD_CLASS_CD VARCHAR(5) COMMENT 'The code indicating if product variant is a dangerous good and additional papers are requried. Business marks this information on product variant level.\n            When not all the product variants are marked as dangerous good , the dangerous goods flag might not be set at the product level.',
	constraint PK_T_DIM_PRODUCT_VARIANT primary key (PROD_VARIANT_SID, DWH_VALID_FROM_TMSP)
)COMMENT='For a given main product there might be various variants with differ in size, color or flavour'
;